writing.exampleCode:
struct Noisy(&'static str);

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("dropping {}", self.0);
    }
}

fn main() {
    let _first = Noisy("first");
    let _second = Noisy("second");
    println!("end of scope");
}

writing.practiceCode:
let a = Noisy("a");
let b = Noisy("b");
drop(a);
println!("after explicit drop");
